package com.finanscore.payment.presentation; import com.finanscore.payment.application.PaymentService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/payments") public class PaymentController{private final PaymentService service;public PaymentController(PaymentService s){service=s;} @GetMapping("/quote") public PaymentService.Quote quote(@RequestParam(defaultValue="EVALUACION_CREDITICIA") String serviceCode,@RequestParam(defaultValue="PEN")String currency){return service.quote(serviceCode,currency);} @PostMapping public PaymentService.Result pay(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key")String idem,@Valid @RequestBody PaymentRequest r){return service.pay(Long.valueOf(jwt.getSubject()),idem,r.requestId(),r.serviceCode(),r.currency(),r.cardBrand(),r.cardNumber(),r.expiry(),r.cvv(),r.correlationId());} public record PaymentRequest(@NotNull UUID requestId,@NotBlank String correlationId,@NotBlank String serviceCode,@NotBlank String currency,@NotBlank String cardBrand,@NotBlank String cardNumber,@NotBlank String expiry,@NotBlank String cvv){} }
